public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        s = s.trim();
        int n = s.length();
        char[] a = s.toCharArray();

        int answer = 0;

        for (int pos = 0; pos < n; pos++) {
            if (a[pos] != '.') continue;

            char[] b = a.clone();
            b[pos] = 'W';

            // Check legality of the placed white stone's chain:
            // in 1D, only the chain containing pos can change from white-side.
            boolean[] vis = new boolean[n];

            int l = pos, r = pos;
            while (l - 1 >= 0 && b[l - 1] == 'W') l--;
            while (r + 1 < n && b[r + 1] == 'W') r++;

            boolean whiteHasLiberty = false;
            if (l - 1 >= 0 && b[l - 1] == '.') whiteHasLiberty = true;
            if (r + 1 < n && b[r + 1] == '.') whiteHasLiberty = true;

            if (!whiteHasLiberty) {
                // Suicide is illegal, even if captures would happen simultaneously.
                continue;
            }

            int captured = 0;

            // Check adjacent black chains that may be captured.
            int[] neighbors = {l - 1, r + 1};
            for (int idx : neighbors) {
                if (idx < 0 || idx >= n || b[idx] != 'B' || vis[idx]) continue;

                int bl = idx, brg = idx;
                while (bl - 1 >= 0 && b[bl - 1] == 'B') bl--;
                while (brg + 1 < n && b[brg + 1] == 'B') brg++;

                for (int i = bl; i <= brg; i++) vis[i] = true;

                boolean blackHasLiberty = false;
                if (bl - 1 >= 0 && b[bl - 1] == '.') blackHasLiberty = true;
                if (brg + 1 < n && b[brg + 1] == '.') blackHasLiberty = true;

                if (!blackHasLiberty) {
                    captured += (brg - bl + 1);
                }
            }

            answer = Math.max(answer, captured);
        }

        System.out.println(answer);
    }
}

