                int end = j;
                while (end < L-1 && board[end+1] == 'B') end++;

                for (int k = start; k <= end; k++) visited[k] = true;

                // Check liberties
                bool hasLiberty = false;
                if (start > 0 && board[start-1] == '.') hasLiberty = true;
                if (end < L-1 && board[end+1] == '.') hasLiberty = true;

                if (!hasLiberty) {
                    captured += end - start + 1;
                    for (int k = start; k <= end; k++) removed[k] = true;
                }
            }
        }

        // Remove captured black stones
        for (int j = 0; j < L; j++) {
            if (removed[j]) board[j] = '.';
        }

        // Check if white chain containing i has liberties (suicide check)
