        while (wstart > 0 && board[wstart-1] == 'W') wstart--;
        while (wend < L-1 && board[wend+1] == 'W') wend++;

        bool whiteHasLiberty = false;
        if (wstart > 0 && board[wstart-1] == '.') whiteHasLiberty = true;
        if (wend < L-1 && board[wend+1] == '.') whiteHasLiberty = true;

