int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    string S;
    cin >> L >> S;

    int ans = 0;

    for (int i = 0; i < L; ++i) {
        if (S[i] != '.') continue;

        // Place white at i and test legality + captured blacks.
        string T = S;
        T[i] = 'W';

        // Find black groups captured by this move.
        vector<int> vis(L, 0);
        int captured = 0;

        for (int j = 0; j < L; ++j) {
            if (T[j] != 'B' || vis[j]) continue;

            int l = j, r = j;
            while (l - 1 >= 0 && T[l - 1] == 'B') --l;
            while (r + 1 < L && T[r + 1] == 'B') ++r;
            for (int k = l; k <= r; ++k) vis[k] = 1;

            bool leftLib = (l - 1 >= 0 && T[l - 1] == '.');
            bool rightLib = (r + 1 < L && T[r + 1] == '.');

            if (!leftLib && !rightLib) {
                captured += (r - l + 1);
                for (int k = l; k <= r; ++k) T[k] = '.';
            }

            j = r;
        }

        // Check if the newly formed white group containing i has a liberty.
        int l = i, r = i;
        while (l - 1 >= 0 && T[l - 1] == 'W') --l;
        while (r + 1 < L && T[r + 1] == 'W') ++r;

        bool leftLib = (l - 1 >= 0 && T[l - 1] == '.');
        bool rightLib = (r + 1 < L && T[r + 1] == '.');

        if (leftLib || rightLib) {
            ans = max(ans, captured);
        }
    }

    cout << ans << '\n';
    return 0;
}

